def transform(grid):
    """Fill background cells between horizontal marker cells with color 2."""
    out = [row[:] for row in grid]
    from collections import Counter
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        markers = [c for c, value in enumerate(row) if value != background]
        if not markers:
            continue
        for c in range(markers[0] + 1, markers[-1]):
            if grid[r][c] == background:
                out[r][c] = 2
    return out
